        "tutorial_s1_title": "Boas-vindas às minas!",
        "tutorial_s1_text": "Olá, novo minerador! Eu sou o Borin. Aqui embaixo você vai minerar ouro, comprar melhorias, derrotar chefes e construir seu próprio império de mineração.\nEste tour é curto e você pode pular a qualquer momento.",
        "tutorial_s2_title": "Minere seu primeiro ouro",
        "tutorial_s2_text": "Clique no botão grande para balançar a picareta. Cada clique rende ouro, e o total aparece no topo. A linha de moedas por segundo mostra sua renda passiva: ouro que chega sozinho.",
        "tutorial_s2_hint": "Clique no botão ou toque em “Avançar” para continuar.",
        "tutorial_s2_done": "Que golpe! O ouro está rolando.",
        "tutorial_s3_title": "Melhorias e renda passiva",
        "tutorial_s3_text": "Gaste seu ouro na loja com melhorias. Algumas deixam cada clique mais forte, outras rendem ouro a cada segundo (CPS), sem precisar clicar.\nCliques são sua renda ativa. O CPS é renda passiva e continua crescendo mesmo quando você está fora.",
        "tutorial_s3_afford": "Você já pode comprar uma melhoria. Experimente!",
        "tutorial_s3_poor": "Ainda sem ouro suficiente? Sem problema. Continue minerando e volte depois.",
        "tutorial_s4_title": "Conheça o caminho",
        "tutorial_s4_text": "A barra de baixo é o seu mapa:\n📜 Missões: metas diárias com recompensas\n🎖️ Passe de Batalha: 60 níveis de recompensas\n🏆 Conquistas: marcos para a vida toda\n⚔️ Aventuras: criação e runas\n💎 Loja: gemas e bônus",
        "tutorial_s5_title": "Chefes e baús com chave",
        "tutorial_s5_text": "Toque no botão Chefes para desafiar um deles. A entrada é grátis: clique rápido para zerar a barra de vida antes que o tempo acabe.\nVencer pode render 🔑 chaves. Gaste-as no Altar das Chaves para abrir baús com moedas, XP, gemas e relíquias.\nSem pressa: os chefes esperam até você estar pronto.",
        "tutorial_s6_title": "Forja, habilidades e Prestígio",
        "tutorial_s6_text_locked": "A aba ⚒️ Prestígio abre a Forja Anã: lá você gasta gemas em habilidades e relíquias permanentes.\nO Prestígio em si ainda está bloqueado. Ele é liberado no nível {level} ou com {coins} moedas no total e reinicia sua partida em troca de gemas que aumentam para sempre tudo o que você ganha. Até lá, é só continuar minerando!",
        "tutorial_s6_text_unlocked": "A aba ⚒️ Prestígio abre a Forja Anã: lá você gasta gemas em habilidades e relíquias permanentes.\nO Prestígio já está disponível. Ele reinicia sua partida em troca de gemas que aumentam para sempre tudo o que você ganha. Sem pressa: confira a recompensa antes.",
        "tutorial_s7_title": "Seu império de ouro espera",
        "tutorial_s7_text": "Isso é tudo o que você precisa saber, minerador! O ciclo é simples: minere ouro, melhore sua produção, cumpra missões e desafie chefes.\nExplore no seu ritmo. Boa sorte lá embaixo!"
