        "tutorial_skip_confirm_title": "튜토리얼을 건너뛸까요?",
        "tutorial_skip_confirm_text": "바로 채굴을 시작할 수 있어요. 튜토리얼은 다시 나타나지 않아요.",
        "tutorial_skip_confirm_yes": "네, 건너뛸게요",
        "tutorial_skip_confirm_no": "계속하기",
        "tutorial_target_missing": "지금은 알려 드릴 수 없지만, 곧 직접 찾게 될 거예요.",
        "tutorial_s1_title": "광산에 오신 것을 환영해요!",
        "tutorial_s1_text": "안녕하세요, 신입 광부님! 저는 보린이에요. 이곳에서 금을 캐고, 업그레이드를 사고, 보스를 쓰러뜨리며 나만의 채굴 제국을 세워 보세요.\n이 안내는 짧고, 언제든지 건너뛸 수 있어요.",
        "tutorial_s2_title": "첫 번째 금을 캐 보세요",
        "tutorial_s2_text": "큰 버튼을 클릭해 곡괭이를 휘둘러 보세요. 클릭할 때마다 금을 얻고, 합계는 맨 위에 표시돼요. 초당 코인 줄은 가만히 있어도 들어오는 패시브 수입을 보여 줘요.",
        "tutorial_s2_hint": "버튼을 한 번 클릭하거나 ‘다음’을 눌러 진행하세요.",
