        "tutorial_s3_title": "업그레이드와 패시브 수입",
        "tutorial_s3_text": "상점에서 금으로 업그레이드를 구매해 보세요. 클릭 한 번을 더 강하게 만드는 것도 있고, 클릭하지 않아도 매초 금을 만들어 내는 것(CPS)도 있어요.\n클릭은 액티브 수입, CPS는 패시브 수입이에요. CPS는 자리를 비운 동안에도 계속 쌓여요.",
        "tutorial_s3_afford": "벌써 업그레이드를 살 수 있어요. 하나 구매해 보세요!",
        "tutorial_s3_poor": "아직 금이 부족한가요? 괜찮아요. 조금 더 캐고 다시 와요.",
        "tutorial_s4_title": "게임 둘러보기",
        "tutorial_s4_text": "아래 바가 여러분의 지도예요:\n📜 퀘스트: 보상을 주는 일일 목표\n🎖️ 배틀 패스: 60단계의 보상\n🏆 업적: 평생 쌓이는 이정표\n⚔️ 모험: 제작과 룬\n💎 상점: 보석과 부스트",
        "tutorial_s5_title": "보스와 열쇠 상자",
        "tutorial_s5_text": "‘보스’ 버튼을 눌러 보스에게 도전하세요. 입장은 무료예요. 제한 시간 안에 빠르게 클릭해서 체력 바를 모두 깎아 보세요.\n승리하면 🔑 열쇠를 얻을 수 있어요. 열쇠 제단에서 사용하면 코인, XP, 보석, 유물이 든 상자를 열 수 있어요.\n서두르지 않아도 돼요. 보스는 준비될 때까지 기다려 줘요.",
        "tutorial_s6_title": "대장간, 스킬, 프레스티지",
        "tutorial_s6_text_locked": "⚒️ 프레스티지 탭에서 드워프 대장간을 열 수 있어요. 여기서 보석으로 영구 스킬과 유물을 얻어요.\n프레스티지 자체는 아직 잠겨 있어요. 레벨 {level} 또는 누적 코인 {coins}에 도달하면 열리고, 진행 상황을 초기화하는 대신 앞으로의 모든 수입을 영구적으로 높여 주는 보석을 받아요. 그때까지는 계속 채굴해 보세요!",
        "tutorial_s6_text_unlocked": "⚒️ 프레스티지 탭에서 드워프 대장간을 열 수 있어요. 여기서 보석으로 영구 스킬과 유물을 얻어요.\n프레스티지는 이미 사용할 수 있어요. 진행 상황을 초기화하는 대신 앞으로의 모든 수입을 영구적으로 높여 주는 보석을 받아요. 서두르지 말고 보상을 먼저 확인해 보세요.",
